param(
  [ValidateSet('x64', 'x86')][string]$Architecture = 'x64',
  [string]$VcVarsVer = '14.29'
)
$ErrorActionPreference = 'Stop'
$vcvarsVer = $VcVarsVer
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$repoRoot = Split-Path $PSScriptRoot -Parent
$metadata = Get-Content (Join-Path $repoRoot 'config/backend.json') -Raw | ConvertFrom-Json
$sourceBuild = $metadata.source_build
if (-not $sourceBuild) { throw 'GPLALL source build metadata is missing' }
$root = Join-Path $repoRoot '.deps/gplall/source-build'
$source = Join-Path $root 'source'
$build = Join-Path $root "build-$Architecture"
$receiptPath = Join-Path $root 'BACKEND-SOURCE.json'
New-Item -ItemType Directory -Force $root | Out-Null

function Invoke-Checked {
  param([string]$Program, [string[]]$Arguments, [string]$WorkingDirectory)
  # Git writes normal fetch progress to stderr. Do not let PowerShell's
  # Stop preference turn that informational stream into a build failure.
  $previousPreference = $ErrorActionPreference
  $nativePreference = $null
  if (Get-Variable PSNativeCommandUseErrorActionPreference -ErrorAction SilentlyContinue) {
    $nativePreference = $PSNativeCommandUseErrorActionPreference
    $PSNativeCommandUseErrorActionPreference = $false
  }
  try {
    $ErrorActionPreference = 'Continue'
    $output = @(& $Program @Arguments 2>&1)
  } finally {
    $ErrorActionPreference = $previousPreference
    if ($null -ne $nativePreference) { $PSNativeCommandUseErrorActionPreference = $nativePreference }
  }
  if ($LASTEXITCODE -ne 0) {
    throw "$Program failed: $LASTEXITCODE`n$($output -join [Environment]::NewLine)"
  }
}

function Test-PatchApplied {
  param([string]$PatchPath)
  # A failed reverse-check is the expected result for a patch that has not
  # been applied. Capture stderr so Stop cannot turn that probe into an error.
  $previousPreference = $ErrorActionPreference
  $ErrorActionPreference = 'Continue'
  try {
    & git -C $source apply --reverse --check --whitespace=nowarn $PatchPath 2>$null
    $exitCode = $LASTEXITCODE
  } finally {
    $ErrorActionPreference = $previousPreference
  }
  return [bool]($exitCode -eq 0)
}

function Resolve-VsDevCmd {
  $vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/Installer/vswhere.exe'
  if (-not (Test-Path -LiteralPath $vswhere)) {
    $vswhere = Join-Path $env:ProgramFiles 'Microsoft Visual Studio/Installer/vswhere.exe'
  }
  if (-not (Test-Path -LiteralPath $vswhere)) { throw 'Visual Studio vswhere.exe not found' }
  $install = (& $vswhere -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath | Select-Object -First 1).Trim()
  if (-not $install) { throw 'Visual Studio C++ tools installation not found' }
  $devcmd = Join-Path $install 'Common7/Tools/VsDevCmd.bat'
  if (-not (Test-Path -LiteralPath $devcmd)) { throw "VsDevCmd.bat not found: $devcmd" }
  [pscustomobject]@{
    Path = $devcmd
    Arch = if ($Architecture -eq 'x86') { 'x86' } else { 'x64' }
  }
}

# Resolve this before checking the build directory. Reusing an existing Meson
# tree must use the same toolchain setup as its initial configuration.
$vs = Resolve-VsDevCmd
$devcmd = $vs.Path
$arch = $vs.Arch

if (-not (Test-Path (Join-Path $source '.git'))) {
  # Fetch the exact superproject commit first. This avoids cloning a moving
  # default branch and then relying on a shallow fetch to find an old pin.
  New-Item -ItemType Directory -Force $source | Out-Null
  Invoke-Checked 'git' @('init', $source) $repoRoot
  Invoke-Checked 'git' @('-C', $source, 'config', 'core.autocrlf', 'false') $repoRoot
  Invoke-Checked 'git' @('-C', $source, 'remote', 'add', 'origin', $sourceBuild.repository) $repoRoot
  Invoke-Checked 'git' @('-C', $source, 'fetch', '--depth=1', 'origin', $sourceBuild.commit) $repoRoot
  Invoke-Checked 'git' @('-C', $source, 'checkout', '--detach', 'FETCH_HEAD') $repoRoot
}
$head = (& git -C $source rev-parse HEAD).Trim()
if ($head -ne $sourceBuild.commit) {
  if ((git -C $source status --porcelain --untracked-files=all)) {
    throw "GPLALL source tree has changes and is pinned to a different commit: $head"
  }
  Invoke-Checked 'git' @('-C', $source, 'fetch', '--depth=1', 'origin', $sourceBuild.commit) $repoRoot
  Invoke-Checked 'git' @('-C', $source, 'checkout', '--detach', $sourceBuild.commit) $repoRoot
  $head = (& git -C $source rev-parse HEAD).Trim()
}
if ($head -ne $sourceBuild.commit) { throw "GPLALL source pin mismatch: $head" }
Invoke-Checked 'git' @('-C', $source, 'submodule', 'update', '--init', '--recursive', '--depth=1') $repoRoot
if ((git -C $source submodule status --recursive | Where-Object { $_ -match '^[+-U]' })) {
  throw 'GPLALL source submodules are not at their pinned commits'
}

# Apply each reviewed source change once to the pinned tree. A clean CI checkout
# always starts from the pin; a prepared tree is accepted only when its receipt
# and reverse patch checks match.
$patches = @($sourceBuild.patches | ForEach-Object { Join-Path $repoRoot $_.path })
$patches += Join-Path $repoRoot 'patches/gplall-msaa-loop/shader.patch'
$marker = Join-Path $root 'PATCHES-APPLIED.json'
$patchData = @($sourceBuild.patches | ForEach-Object {
  $path = Join-Path $repoRoot $_.path
  if (-not (Test-Path -LiteralPath $path)) { throw "Missing GPLALL source patch: $path" }
  $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower()
  if ($hash -ne $_.sha256.ToLower()) { throw "GPLALL source patch checksum mismatch: $($_.id)" }
  [ordered]@{ id = $_.id; path = $_.path; sha256 = $hash }
})
$shaderPatchPath = Join-Path $repoRoot 'patches/gplall-msaa-loop/shader.patch'
if (-not (Test-Path -LiteralPath $shaderPatchPath)) { throw "Missing GPLALL shader patch: $shaderPatchPath" }
$shaderHash = (Get-FileHash -LiteralPath $shaderPatchPath -Algorithm SHA256).Hash.ToLower()
if ($metadata.modification.source_patch.sha256 -and $shaderHash -ne $metadata.modification.source_patch.sha256.ToLower()) {
  throw 'GPLALL shader patch checksum mismatch'
}
$expectedMarker = [ordered]@{ source_commit = $head; patches = $patchData; shader_patch = $shaderHash }

$markerValid = $false
if (Test-Path -LiteralPath $marker) {
  try {
    $actualMarker = Get-Content -LiteralPath $marker -Raw | ConvertFrom-Json
    $markerValid = ($actualMarker.source_commit -eq $expectedMarker.source_commit) -and
      ((ConvertTo-Json -InputObject @($actualMarker.patches) -Depth 6 -Compress) -eq
       (ConvertTo-Json -InputObject @($expectedMarker.patches) -Depth 6 -Compress)) -and
      ($actualMarker.shader_patch -eq $expectedMarker.shader_patch)
  } catch {
    $markerValid = $false
  }
  if (-not $markerValid) { throw 'GPLALL source patch receipt is missing or does not match the pinned inputs' }
}

$applied = @($patches | ForEach-Object { Test-PatchApplied $_ })
if ($applied -contains $false) {
  if ($markerValid) { throw 'GPLALL source patch receipt says applied, but the source tree does not match it' }
  $sourceStatus = git -C $source status --porcelain --untracked-files=all
  if (($applied -notcontains $true) -and $sourceStatus) {
    throw 'GPLALL source tree has unexpected changes before patch application'
  }
  for ($i = 0; $i -lt $patches.Count; $i++) {
    if (Test-PatchApplied $patches[$i]) { continue }
    & git -C $source apply --check --whitespace=nowarn $patches[$i] 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) { throw "GPLALL source patch cannot be applied: $($patches[$i])" }
    Invoke-Checked 'git' @('-C', $source, 'apply', '--whitespace=nowarn', $patches[$i]) $repoRoot
  }
  $applied = @($patches | ForEach-Object { Test-PatchApplied $_ })
}
if (($applied -contains $false) -or ($applied.Count -ne $patches.Count)) {
  throw 'GPLALL source patches were not applied completely'
}
if (-not $markerValid) {
  [System.IO.File]::WriteAllText($marker, ($expectedMarker | ConvertTo-Json -Depth 6), $utf8NoBom)
}

if (-not (Test-Path -LiteralPath (Join-Path $build 'build.ninja'))) {
  $setup = "call `"$devcmd`" -arch=$arch -host_arch=x64 -vcvars_ver=$vcvarsVer && python -m mesonbuild.mesonmain setup `"$build`" `"$source`" --backend ninja --buildtype release -Denable_d3d8=false -Denable_dxgi=false -Denable_d3d10=false -Denable_d3d11=false -Denable_d3d9=true --wrap-mode=nodownload"
  Invoke-Checked 'cmd.exe' @('/d', '/s', '/c', $setup) $repoRoot
}
$compile = "call `"$devcmd`" -arch=$arch -host_arch=x64 -vcvars_ver=$vcvarsVer && python -m mesonbuild.mesonmain compile -C `"$build`""
Invoke-Checked 'cmd.exe' @('/d', '/s', '/c', $compile) $repoRoot
$dll = Join-Path $build 'src/d3d9/d3d9.dll'
if (-not (Test-Path $dll)) { throw "GPLALL $Architecture D3D9 DLL was not produced" }

$entries = @{}
if (Test-Path $receiptPath) { $entries = Get-Content $receiptPath -Raw | ConvertFrom-Json }
$hash = (Get-FileHash $dll -Algorithm SHA256).Hash.ToLower()
$entries | Add-Member -NotePropertyName source_commit -NotePropertyValue $head -Force
$entries | Add-Member -NotePropertyName repository -NotePropertyValue $sourceBuild.repository -Force
$entries | Add-Member -NotePropertyName patches -NotePropertyValue @($sourceBuild.patches | ForEach-Object { $_.id }) -Force
$entries | Add-Member -NotePropertyName shader_patch -NotePropertyValue 'patches/gplall-msaa-loop/shader.patch' -Force
$entries | Add-Member -NotePropertyName compiler -NotePropertyValue 'MSVC 14.29 (workflow-selected Visual Studio toolset)' -Force
$entries | Add-Member -NotePropertyName vcvars_ver -NotePropertyValue $vcvarsVer -Force
$entries | Add-Member -NotePropertyName source_tree -NotePropertyValue $source -Force
if (-not $entries.outputs) { $entries | Add-Member -NotePropertyName outputs -NotePropertyValue ([pscustomobject]@{}) -Force }
$entries.outputs | Add-Member -NotePropertyName $Architecture -NotePropertyValue ([pscustomobject]@{ path = $dll; sha256 = $hash }) -Force
[System.IO.File]::WriteAllText($receiptPath, ($entries | ConvertTo-Json -Depth 10), $utf8NoBom)
Write-Output $dll
